import {publicRoutes,privateRoutes,isPrivatePage,publicContent,bindPublicHelp,privateContent,bindPrivatePage} from './pages.js';
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=c=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}).format(c/100);
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const niceDate=d=>d?new Date(d+'T12:00:00').toLocaleDateString('pt-BR',{day:'2-digit',month:'short'}):'Sem data';
const labels={sent:'Enviado',contact:'Em contato',negotiation:'Negociação',won:'Ganho',lost:'Perdido'};
const paths={home:'M3 10l9-7 9 7v10H3z M9 20v-7h6v7',arrow:'M5 12h14m-5-5 5 5-5 5',check:'m5 12 4 4L19 6',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',chart:'M4 20V10m8 10V4m8 16v-8',clock:'M12 8v5l3 2 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',shield:'M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6z m-4 9 3 3 5-5',file:'M6 3h8l4 4v14H6z M14 3v5h5 M9 12h6m-6 4h6',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3m20 0v-3a4 4 0 0 0-3-4 M13 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0m3-4a4 4 0 0 1 0 8',plug:'M8 3v5m8-5v5 M6 8h12v3a6 6 0 0 1-12 0z M12 17v4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',card:'M3 5h18v14H3z M3 10h18m-14 5h4',plus:'M12 5v14M5 12h14',close:'m6 6 12 12M6 18 18 6',play:'m9 5 11 7-11 7z',out:'M9 5H4v14h5m4-14 7 7-7 7m-5-7h12',upload:'M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5',mail:'M3 5h18v14H3z m0 0 9 7 9-7',list:'M9 5h12M9 12h12M9 19h12M3 5h1M3 12h1M3 19h1',chevron:'m9 5 7 7-7 7'};
const icon=n=>`<svg class="icon" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.file}"/></svg>`;
const brand=()=>'<a class="brand" href="/" aria-label="Branchly, início"><img src="/logo.svg" alt="">branchly</a>';
const btn=(text,href,cls='')=>`<a class="btn ${cls}" href="${href}">${text}</a>`;
const root=$('#root');let me=null,proposals=[],tasks=[],isDemo=location.pathname==='/demo',timer=null;
const nav=()=>`<div class="wrap"><header class="nav">${brand()}<button class="mobile-menu btn small secondary" id="public-menu-toggle" aria-expanded="false" aria-controls="public-mobile-nav" aria-label="Abrir menu de navegação">${icon('list')}</button><nav class="navlinks" aria-label="Principal"><a href="/produto">Produto</a><a href="/como-funciona">Como funciona</a><a href="/integracoes">Integrações</a><a href="/precos">Preços</a></nav><div class="nav-actions"><a href="/entrar">Entrar</a>${btn('Começar agora '+icon('arrow'),'/cadastro','lime')}</div></header><nav class="mobile-nav" id="public-mobile-nav" aria-label="Menu mobile" hidden><a href="/produto">Produto</a><a href="/como-funciona">Como funciona</a><a href="/integracoes">Integrações</a><a href="/precos">Preços</a><a href="/ajuda">Ajuda</a><a href="/entrar">Entrar na conta</a></nav></div>`;
const footer=()=>`<div class="wrap"><footer class="footer"><div>${brand()}<p>Cada oportunidade, um próximo passo.</p></div><nav aria-label="Rodapé"><a href="/produto">Produto</a><a href="/precos">Preços</a><a href="/privacidade">Privacidade</a><a href="/termos">Termos</a><a href="/seguranca">Segurança</a><a href="/ajuda">Ajuda</a><a href="/contato">Contato</a><a href="/solucoes/climatizacao">Climatização</a></nav><span>© ${new Date().getFullYear()} Branchly</span></footer></div>`;
document.addEventListener('click',event=>{const button=event.target.closest('#public-menu-toggle');if(!button)return;const menu=$('#public-mobile-nav');if(!menu)return;menu.hidden=!menu.hidden;button.setAttribute('aria-expanded',String(!menu.hidden));button.setAttribute('aria-label',menu.hidden?'Abrir menu de navegação':'Fechar menu de navegação');});
function toast(text){const t=$('#toast');t.textContent=text;t.classList.add('visible');setTimeout(()=>t.classList.remove('visible'),5000);}
async function api(url,method='GET',data){const r=await fetch(url,{method,headers:method==='GET'?{}:{'Content-Type':'application/json'},...(data!==undefined?{body:JSON.stringify(data)}:{})});const d=await r.json();if(!r.ok){if(r.status===401&&location.pathname.startsWith('/app'))location.href='/entrar';throw new Error(d.error||'Não foi possível concluir.');}return d;}
function motion(){if(!matchMedia('(prefers-reduced-motion: reduce)').matches){document.body.classList.add('js-motion');const ob=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');ob.unobserve(e.target);}}),{threshold:.08});$$('.reveal').forEach(e=>ob.observe(e));}}
const preview=()=>`<div class="product-window"><div class="window-top"><div class="dots"><i></i><i></i><i></i></div><span>Seu comercial, em movimento</span>${icon('shield')}</div><div class="window-body"><div class="mini-heading"><h3>Próximos passos</h3><span class="badge green">Demonstração</span></div><div class="proposal-preview"><div class="avatar">CA</div><div><strong>Casa Aurora</strong><small>Instalação de climatização</small></div><b>R$ 8.400</b></div><div class="connector"></div><div class="ai-preview"><h4>${icon('spark')} Uma conversa para retomar</h4><p>Olá! Conseguiu avaliar a proposta de climatização? Posso esclarecer algum ponto para ajudar na decisão?</p><div class="tiny-footer"><span>Você revisa antes de enviar</span><b>Sugestão de mensagem →</b></div></div><div class="connector"></div><div class="outcome">${icon('check')} Próximo contato organizado. Nada depende da memória.</div><small class="muted">Exemplo ilustrativo com dados fictícios.</small></div></div>`;
const faq=()=>`<div class="faq"><details><summary>A Branchly substitui minha equipe comercial?</summary><p>Ela organiza o acompanhamento e ajuda a preparar mensagens. Sua equipe continua responsável pelo relacionamento, pelas decisões e pela aprovação de cada envio.</p></details><details><summary>Preciso conectar o WhatsApp para começar?</summary><p>Não. Você já pode cadastrar propostas, importar CSV e organizar tarefas. O envio via WhatsApp depende de configuração da API oficial da Meta e das regras de atendimento.</p></details><details><summary>A IA envia mensagens sozinha?</summary><p>Não. As sugestões passam por sua revisão. O envio exige uma ação explícita e autorização registrada para contato.</p></details><details><summary>A Branchly garante mais vendas?</summary><p>Não. Ela ajuda a reduzir esquecimentos e a organizar a rotina. O resultado depende da sua oferta, da equipe, do volume de propostas e das decisões dos clientes.</p></details><details><summary>O que acontece depois dos 30 dias?</summary><p>Você decide se continua. A proposta de assinatura padrão é de R$ 1.490/mês. A ativação do pagamento depende da disponibilidade do checkout; a criação da conta não gera cobrança automática.</p></details></div>`;
function landing(){root.innerHTML=nav()+`<main id="main"><div class="wrap"><section class="hero"><div class="reveal"><div class="eyebrow">Acompanhamento comercial com IA</div><h1>O orçamento foi.<br><span>A oportunidade<br>continua.</span></h1><p>Transforme propostas sem retorno em próximos passos claros. Sua equipe acompanha. A IA ajuda a preparar a conversa.</p><div class="actions">${btn('Organizar meus orçamentos '+icon('arrow'),'/cadastro','lime')}${btn(icon('play')+' Ver em ação','/demo','secondary')}</div><p class="fine">Comece sem conectar integrações. Nenhuma cobrança ao criar a conta.</p></div><div class="reveal">${preview()}</div></section><div class="proofstrip"><span>${icon('file')} Propostas em um só lugar</span><span>${icon('spark')} Sugestões com contexto</span><span>${icon('shield')} Aprovação humana</span><span>${icon('clock')} Próximos contatos visíveis</span></div><section class="section"><div class="sectionhead reveal"><div class="eyebrow">Menos dispersão. Mais continuidade.</div><h2>Conquistar o contato<br>é só o começo.</h2><p>Entre enviar a proposta e receber uma decisão, existe um trabalho que não pode depender da memória.</p></div><div class="cards"><article class="card reveal"><span class="number">01 / ORGANIZAR</span><div class="feature-icon">${icon('file')}</div><h3>Saiba onde cada<br>negociação está.</h3><p>Cliente, valor, contexto e próximo contato. As informações essenciais, sem complicar sua rotina.</p></article><article class="card reveal"><span class="number">02 / ACOMPANHAR</span><div class="feature-icon">${icon('clock')}</div><h3>Abra o dia sabendo<br>quem precisa de atenção.</h3><p>Uma fila clara de tarefas e propostas com contato previsto. Sua equipe sabe por onde começar.</p></article><article class="card reveal"><span class="number">03 / AVANÇAR</span><div class="feature-icon">${icon('spark')}</div><h3>Retome a conversa<br>com mais contexto.</h3><p>A IA prepara uma sugestão a partir da proposta. Você ajusta, aprova e decide o próximo passo.</p></article></div></section><section class="dark-section reveal" id="como-funciona"><div class="eyebrow">Veja a lógica em poucos segundos</div><h2>Da proposta enviada<br>ao próximo movimento.</h2><div class="demo-steps" role="tablist" aria-label="Etapas da demonstração"><button class="demo-step active" role="tab" data-step="0">01. Proposta</button><button class="demo-step" role="tab" data-step="1">02. Acompanhamento</button><button class="demo-step" role="tab" data-step="2">03. Decisão</button></div><div class="demo-stage" id="demo-stage" role="tabpanel"></div><div class="progress"><i id="demo-progress"></i></div><div class="actions demo-controls"><button class="btn small lime" id="demo-play">Pausar animação</button><a class="btn small secondary" href="/demo">Explorar a demonstração ${icon('arrow')}</a></div><p class="subtle">Fluxo ilustrativo. A animação não representa uma venda real.</p></section><section class="section split"><div class="reveal"><div class="eyebrow">Feita para empresas de serviços</div><h2>Clareza para quem<br>tem trabalho de sobra.</h2><p class="muted">Começando por empresas de climatização que precisam dar continuidade a instalações, manutenções e propostas em andamento.</p><ul class="check-list"><li>${icon('check')} Cadastro manual ou importação por planilha</li><li>${icon('check')} Situação e valor de cada proposta</li><li>${icon('check')} Tarefas e próximos contatos</li><li>${icon('check')} Visibilidade dos resultados registrados</li></ul>${btn('Conhecer o produto '+icon('arrow'),'/produto','secondary')}</div><div class="price-card featured reveal"><div class="eyebrow">Piloto de lançamento</div><h3>Um fluxo simples.<br>Uma rotina mais clara.</h3><div class="price">R$ 490 <small>/ 30 dias</small></div><p>Oferta inicial para começar com um processo comercial definido.</p><ul class="check-list"><li>${icon('check')} Organização de orçamentos e tarefas</li><li>${icon('check')} Até 3 usuários por empresa</li><li>${icon('check')} IA e envios conforme configuração</li></ul>${btn('Criar minha conta '+icon('arrow'),'/cadastro','lime')}<p class="subtle">Sem cobrança automática no cadastro. Plano padrão proposto: R$ 1.490/mês após o piloto.</p></div></section><section class="section"><div class="sectionhead"><div class="eyebrow">Antes de começar</div><h2>Respostas claras.</h2></div>${faq()}</section><section class="closing reveal"><div class="eyebrow">Seu próximo passo começa aqui</div><h2>Mais continuidade.<br>Menos oportunidades esquecidas.</h2><p>Veja o fluxo funcionando na demonstração. Quando fizer sentido, organize seus primeiros orçamentos.</p>${btn('Experimentar a demonstração '+icon('arrow'),'/demo','lime')}</section></div></main>`+footer();setupStory();motion();}
function setupStory(){let step=0,playing=!matchMedia('(prefers-reduced-motion: reduce)').matches;const stages=[['PROPOSTA ORGANIZADA','Casa Aurora · Instalação de climatização','R$ 8.400 em uma proposta enviada. O valor faz parte de uma demonstração fictícia, não de receita confirmada.'],['PRÓXIMO CONTATO DEFINIDO','Uma mensagem que considera o contexto','“Conseguiu avaliar a proposta? Posso esclarecer algum ponto?” Você revisa o texto e escolhe quando agir.'],['SITUAÇÃO ATUALIZADA','Uma decisão registrada pela sua equipe','Avançou, ganhou ou perdeu? O histórico mostra o que aconteceu, com base no que a equipe registrou.']];function show(n){step=n;const s=stages[n];$('#demo-stage').innerHTML=`<div class="page-enter"><span class="stage-label">${s[0]}</span><h3>${s[1]}</h3><p>${s[2]}</p></div>`;$$('[data-step]').forEach((e,i)=>{e.classList.toggle('active',i===n);e.setAttribute('aria-selected',i===n?'true':'false');});$('#demo-progress').style.width=((n+1)/3*100)+'%';}show(0);const play=$('#demo-play');function label(){play.textContent=playing?'Pausar animação':'Reproduzir animação';}label();$$('[data-step]').forEach(e=>e.onclick=()=>{playing=false;label();show(Number(e.dataset.step));});play.onclick=()=>{playing=!playing;label();};timer=setInterval(()=>{if(playing&&!document.hidden)show((step+1)%3);},4500);}
function publicPage(type){if(publicRoutes.includes(type)){root.innerHTML=nav()+`<main id="main" class="wrap">${publicContent(type,{icon,btn})}</main>`+footer();bindPublicHelp(root);motion();return;}let content='';if(type==='/produto'){content=`<section class="page-intro"><div class="eyebrow">Produto</div><h1>Uma rotina comercial.<br>Sem pontas soltas.</h1><p>Comece pelos orçamentos que você já tem. Organize, acompanhe e registre o próximo movimento.</p></section><section class="split section"><div>${preview()}</div><div><h2>O essencial<br>para continuar.</h2><ul class="check-list"><li>${icon('check')} Pipeline com cinco situações comerciais</li><li>${icon('check')} Fila de tarefas e próximos contatos</li><li>${icon('check')} Cadastro de contexto e autorização de contato</li><li>${icon('check')} Importação e exportação CSV</li><li>${icon('check')} Sugestões de IA quando configuradas</li></ul>${btn('Testar o fluxo '+icon('arrow'),'/demo','lime')}</div></section><section class="section"><div class="sectionhead"><h2>Integrações com<br>responsabilidade.</h2><p>OpenAI para sugestões, Meta para atendimento via WhatsApp, Efí para assinatura, Resend para e-mails e um webhook de teste para n8n. As conexões precisam de credenciais e homologação antes do uso real.</p></div></section>`;}else if(type==='/precos'){content=`<section class="page-intro"><div class="eyebrow">Preços transparentes</div><h1>Comece com foco.<br>Cresça com clareza.</h1><p>O cadastro não gera cobrança. A contratação é feita separadamente, pelo checkout quando estiver disponível.</p></section><div class="split"><article class="price-card featured"><span class="eyebrow">Oferta de lançamento</span><h3>Piloto · 30 dias</h3><div class="price">R$ 490</div><p>Para colocar um fluxo comercial em uso.</p><ul class="check-list"><li>${icon('check')} Uma empresa, até três usuários</li><li>${icon('check')} Cadastro, importação e tarefas</li><li>${icon('check')} Visão das negociações</li><li>${icon('check')} IA limitada a 20 sugestões/dia por padrão</li></ul>${btn('Criar conta','/cadastro','lime')}</article><article class="price-card"><span class="eyebrow">Continuidade após o piloto</span><h3>Branchly</h3><div class="price">R$ 1.490 <small>/ mês</small></div><p>Preço proposto da assinatura padr��o.</p><ul class="check-list"><li>${icon('check')} O mesmo fluxo com uso contínuo</li><li>${icon('check')} Relatórios e histórico</li><li>${icon('check')} Até 2.000 propostas nesta versão</li><li>${icon('check')} Até 100 propostas por importação</li></ul>${btn('Conhecer o sistema','/demo','secondary')}</article></div><p class="subtle">Consumo e disponibilidade das integrações dependem da configuração. Custos de mensageria e serviços de terceiros devem ser definidos na contratação. O checkout usa o preço configurado pelo operador, que deve corresponder à oferta exibida.</p><section class="section">${faq()}</section>`;}else{const legal={ '/seguranca':['Segurança por princípio.','Acesso à sua empresa','As rotas privadas exigem sessão válida e cada operação consulta o vínculo do usuário com a empresa. Os dados de uma empresa não são compartilhados com outra.','Controle das mensagens','Sugestões de IA precisam de revisão e envio explícito. Configurações do WhatsApp são criptografadas no servidor. O envio de texto exige autorização registrada e uma mensagem recebida nas últimas 24 horas.','Operação responsável','Senhas são protegidas com scrypt. Cookies de produção usam HttpOnly, Secure e SameSite. A implantação exige HTTPS. Ainda são necessários revisão independente, monitoramento e testes reais dos provedores antes de operar com clientes.'], '/privacidade':['Seus dados, com clareza.','O que esta versão trata','Nome, e-mail, credencial protegida, dados da empresa, propostas, contatos, tarefas, mensagens e registros de operação. Cadastre somente informações necessárias e obtidas de forma adequada.','Quando os dados saem da plataforma','Sugestões usam nome, serviço e notas da proposta na OpenAI. Envios usam os provedores configurados de WhatsApp e e-mail. Pagamentos são processados no Efí. Evite inserir dados sensíveis nas notas.','Antes do lançamento comercial','Esta é uma minuta operacional. A empresa operadora, contato de privacidade, retenção, contratos com fornecedores e canal de exclusão precisam ser preenchidos antes de abrir o serviço a clientes. Não há rastreadores de publicidade nesta versão. Registramos contagens de abertura da demonstração, cadastro e ações de ativação, sem identificar visitantes anônimos. A sessão do navegador evita repetir contagens de abertura.'], '/termos':['Uma relação transparente.','Escopo do serviço','A Branchly organiza propostas e tarefas e oferece conexões opcionais com serviços de terceiros. A equipe é responsável pelos dados cadastrados, pelas mensagens aprovadas e pelo uso autorizado dos contatos.','Resultados e cobrança','A plataforma não garante vendas ou faturamento. Criar uma conta não gera cobrança. Checkout e renovação dependem da contratação e do preço efetivamente exibido pelo processador de pagamentos.','Antes da oferta pública','Esta é uma minuta para revisão: faltam identificação legal do fornecedor, suporte, regras comerciais de cancelamento, retenção e responsabilidades detalhadas. Não utilizar esta minuta como contrato final sem completar esses dados.']};const a=legal[type];content=`<section class="page-intro"><div class="eyebrow">Branchly</div><h1>${a[0]}</h1></section><article class="legal">${[1,3,5].map(i=>`<h3>${a[i]}</h3><p>${a[i+1]}</p>`).join('')}<p class="subtle">Versão inicial · 19 de outubro de 2026.</p></article>`;}root.innerHTML=nav()+`<main id="main" class="wrap">${content}</main>`+footer();motion();}
function field(name,label,type='text',placeholder='',required=true,value=''){return `<label class="field">${label}<input name="${name}" type="${type}" placeholder="${placeholder}" value="${esc(value)}" ${required?'required':''} ${type==='password'?'minlength="10" autocomplete="new-password"':''} ${type==='email'?'autocomplete="email"':''}></label>`;}
function authPage(){const p=location.pathname,register=p==='/cadastro',login=p==='/entrar',forgot=p==='/recuperar-senha',reset=p==='/redefinir-senha',verify=p==='/confirmar-email',invite=p==='/convite';let title=register?'Seu próximo passo.':login?'Bom ter você de volta.':forgot?'Vamos recuperar seu acesso.':reset?'Escolha uma nova senha.':verify?'Confirme seu e-mail.':'Faça parte da equipe.';root.innerHTML=`<main id="main" class="auth-layout"><aside class="auth-story">${brand()}<div><div class="eyebrow">Cada oportunidade, um próximo passo.</div><h2>O comercial continua.<br>Com você no controle.</h2><p>Organize propostas, prepare conversas e dê continuidade ao trabalho que sua equipe já começou.</p></div><div class="mini-tags"><span>Clareza</span><span>·</span><span>Continuidade</span><span>·</span><span>Controle</span></div></aside><section class="auth-form"><div class="auth-inner"><h1>${title}</h1><p>${register?'Crie sua empresa e cadastre o primeiro orçamento. Sete dias de acesso inicial, sem cobrança automática.':login?'Entre para acompanhar suas oportunidades.':forgot?'Enviaremos um link se houver uma conta com este e-mail.':verify?'Use o botão para confirmar o link recebido.':'Defina seus dados para continuar.'}</p><form id="auth-form">${register||invite?field('name','Seu nome','text','Como podemos chamar você?'):''}${register?field('organization','Nome da empresa','text','Sua empresa'):''}${register||login||forgot?field('email','E-mail profissional','email','voce@empresa.com.br'):''}${!forgot&&!verify?field('password','Senha','password','Pelo menos 10 caracteres'):''}${register?'<label class="checkbox"><input type="checkbox" required> <span>Li as <a href="/termos" class="inline-link">condições desta versão</a> e a <a href="/privacidade" class="inline-link">política de privacidade</a>.</span></label>':''}<p class="form-error" id="form-error" role="alert"></p><button class="btn lime" type="submit">${register?'Criar minha conta':login?'Entrar':forgot?'Enviar instruções':verify?'Confirmar e-mail':'Continuar'} ${icon('arrow')}</button></form><p class="auth-foot">${login?'<a href="/recuperar-senha">Esqueci minha senha</a><br><br>Ainda não tem conta? <a href="/cadastro">Começar agora</a>':register?'Já tem conta? <a href="/entrar">Entrar</a>':'<a href="/entrar">Voltar para entrar</a>'}</p><p class="auth-foot"><a href="/demo">Explorar a demonstração primeiro</a></p></div></section></main>`;if(login)$('[name=password]').autocomplete='current-password';$('#auth-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,button=$('button',form);button.disabled=true;$('#form-error').textContent='';const d=Object.fromEntries(new FormData(form));if(reset||verify||invite)d.token=new URLSearchParams(location.search).get('token')||'';const endpoint=register?'register':login?'login':forgot?'forgot':reset?'reset':'verify';try{const result=await api(invite?'/api/invitations/accept':'/api/auth/'+endpoint,'POST',d);if(result.requires_confirmation){toast(result.message);form.reset();$('#form-error').textContent=result.message;return;}if(register||login||invite)location.href='/app';else{toast(result.message);if(reset||verify)setTimeout(()=>location.href='/entrar',1200);}}catch(err){$('#form-error').textContent=err.message;}finally{button.disabled=false;}};}
const menu=[['/app','Visão geral','home'],['/app/orcamentos','CRM','chart'],['/app/clientes','Contatos','users'],['/app/atividades','Tarefas','clock'],['/app/relatorios','Analytics','chart'],['/app/integracoes','Integrações','plug'],['/app/equipe','Equipe','users'],['/app/assinatura','Financeiro','card'],['/app/configuracoes','Configurações','settings'],['/app/primeiros-passos','Primeiros passos','check'],['/app/perfil','Meu perfil','users'],['/app/seguranca','Segurança','shield'],['/app/historico','Histórico','list'],['/app/ajuda','Central de ajuda','file']];
