function shell(page){root.innerHTML=`${isDemo?'<div class="demo-banner">Demonstração interativa · Dados fictícios · Alterações não são salvas nem enviam mensagens.<a href="/cadastro">Criar conta real →</a></div>':''}<div class="app-layout"><aside class="sidebar">${brand()}<div class="side-label">Workspace</div><nav aria-label="Aplicação">${menu.map(([url,label,ico])=>`<a href="${isDemo?'/demo?view='+encodeURIComponent(url):url}" class="side-link ${(page===url||(url==='/app/orcamentos'&&page.startsWith(url+'/'))||(url==='/app/clientes'&&page.startsWith(url+'/')))?'active':''}" ${isDemo?`data-demo-view="${url}"`:''}>${icon(ico)}${label}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="side-user"><div class="avatar">${esc((me?.name||'D').slice(0,2).toUpperCase())}</div><div><strong>${esc(me?.name||'Conta demonstrativa')}</strong><br>${esc(me?.organization||'Clima Studio')}</div></div><button class="btn small ghost" id="logout">${icon('out')}${isDemo?'Voltar ao site':'Sair da conta'}</button></div></aside><div><header class="app-top"><span>Workspace <strong>/ ${esc(me?.organization||'Clima Studio')}</strong></span><span>${new Date().toLocaleDateString('pt-BR',{day:'numeric',month:'long'})} <button class="btn small ghost" id="top-logout">Sair</button></span></header><main class="app-content page-enter" id="main"><div class="loading"><span class="spinner"></span></div></main></div></div>`;const signOut=async()=>{try{if(!isDemo)await api('/api/auth/logout','POST',{});location.href='/';}catch(error){toast(error.message);}};$('#logout').onclick=signOut;$('#top-logout').onclick=signOut;$$('[data-demo-view]').forEach(a=>a.onclick=e=>{e.preventDefault();history.replaceState({},'',a.href);renderApp(a.dataset.demoView);});}
