function statsHTML(){const open=proposals.filter(p=>!['won','lost'].includes(p.status)),won=proposals.filter(p=>p.status==='won'),overdue=open.filter(p=>p.next_date&&p.next_date<=today()),conversion=proposals.length?Math.round(won.length/proposals.length*100):0;return `<div class="stats"><article class="stat highlight"><div class="stat-label">Pipeline aberto ${icon('chart')}</div><strong>${money(open.reduce((s,p)=>s+p.value_cents,0))}</strong><small>Valor de oportunidades em andamento</small></article><article class="stat"><div class="stat-label">Receita confirmada ${icon('check')}</div><strong>${money(won.reduce((s,p)=>s+p.value_cents,0))}</strong><small>Negócios marcados como ganhos</small></article><article class="stat"><div class="stat-label">Ações pendentes ${icon('clock')}</div><strong>${overdue.length}</strong><small>Próximos contatos até hoje</small></article><article class="stat"><div class="stat-label">Conversão registrada ${icon('spark')}</div><strong>${conversion}%</strong><small>Com base nos dados desta visão</small></article></div>`;}
