function proposalTable(list){return list.length?`<div class="table-scroll"><table><thead><tr><th>Cliente / serviço</th><th>Valor</th><th>Situação</th><th>Próximo contato</th><th></th></tr></thead><tbody>${list.map(p=>`<tr><td><div class="client-cell"><div class="avatar">${esc(p.client.slice(0,2).toUpperCase())}</div><div><strong><a href="${isDemo?'/demo?view='+encodeURIComponent('/app/orcamentos/'+p.id):'/app/orcamentos/'+p.id}">${esc(p.client)}</a></strong><small>${esc(p.title)}</small></div></div></td><td class="value-cell">${money(p.value_cents)}</td><td>${statusBadge(p.status)}</td><td>${niceDate(p.next_date)}</td><td><button class="btn small ghost" data-open="${p.id}" aria-label="Abrir orçamento de ${esc(p.client)}">${icon('chevron')}</button></td></tr>`).join('')}</tbody></table></div>`:empty('Seu primeiro orçamento começa aqui.','Cadastre uma proposta e organize o próximo contato. Nenhum dado fictício é adicionado à sua conta.','<button class="btn lime" data-new>Adicionar orçamento</button>');}
function tasksHTML(list){return list.length?list.map(t=>`<label class="task ${t.done?'done':''}"><input type="checkbox" data-task="${t.id}" ${t.done?'checked':''}><span><b>${esc(t.title)}</b><small>${esc(t.client||'Atividade da equipe')} · ${niceDate(t.due_date)}</small></span></label>`).join(''):empty('Uma fila mais clara.','Crie uma tarefa para lembrar do próximo contato.','<button class="btn small secondary" data-new-task>Criar tarefa</button>');}
